    "thumbnailSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"-30.0 -30.0 1554.0 545.0\" width=\"1554.0\" height=\"545.0\">\n  <defs>\n    <style>\n      @import url(\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&amp;display=swap\");\n      text { font-family: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif; }\n    </style>\n    <marker id=\"arrowhead\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n      <polygon points=\"0 0, 10 3.5, 0 7\" fill=\"#2563EB\" />\n    </marker>\n    <marker id=\"arrowhead-hero\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n      <polygon points=\"0 0, 10 3.5, 0 7\" fill=\"#D93829\" />\n    </marker>\n    <marker id=\"arrowhead-danger\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n      <polygon points=\"0 0, 10 3.5, 0 7\" fill=\"#DC2626\" />\n    </marker>\n  </defs>\n  <rect x=\"-30.0\" y=\"-30.0\" width=\"1554.0\" height=\"545.0\" fill=\"#F8FAFC\" />\n  <rect x=\"10.0\" y=\"10.0\" width=\"1474.0\" height=\"465.0\" rx=\"0.0\" fill=\"transparent\" stroke=\"#CBD5E1\" stroke-width=\"1.5\" />\n  <text x=\"30.0\" y=\"46.0\" fill=\"#64748B\" font-size=\"11px\" font-weight=\"400\">SKETION TEMPLATE LIBRARY · ESTUDIO · INTER VECTORIAL</text>\n  <rect x=\"30.0\" y=\"70.0\" width=\"380.0\" height=\"370.0\" rx=\"6.0\" fill=\"#FFFFFF\" stroke=\"#CBD5E1\" stroke-width=\"1.5\" />\n  <text x=\"50.0\" y=\"102.0\" fill=\"#D93829\" font-size=\"12px\" font-weight=\"400\">PREGUNTAS CLAVE &amp; INDICIOS</text>\n  <text x=\"50.0\" y=\"141.0\" fill=\"#334155\" font-size=\"11px\" font-weight=\"400\">* Concepto principal de la sesion\n* Pregunta central de examen\n* Formulas a memorizar\n* Definiciones clave</text>\n  <rect x=\"430.0\" y=\"70.0\" width=\"680.0\" height=\"260.0\" rx=\"6.0\" fill=\"#FFFFFF\" stroke=\"#CBD5E1\" stroke-width=\"1.5\" />\n  <text x=\"450.0\" y=\"102.0\" fill=\"#0F172A\" font-size=\"12px\" font-weight=\"400\">NOTAS DETALLADAS &amp; DESARROLLO</text>\n  <text x=\"450.0\" y=\"141.0\" fill=\"#475569\" font-size=\"11px\" font-weight=\"400\">1. Explicacion paso a paso del teorema o modelo analitico\n2. Casos de aplicacion practica y ejemplos numericos\n3. Observaciones del docente y advertencias sobre errores comunes\n4. Demostracion formal y propiedades estructurales</text>\n  <rect x=\"430.0\" y=\"345.0\" width=\"680.0\" height=\"95.0\" rx=\"6.0\" fill=\"#FFF5F2\" stroke=\"#D93829\" stroke-width=\"1.5\" />\n  <text x=\"450.0\" y=\"371.0\" fill=\"#D93829\" font-size=\"11px\" font-weight=\"400\">RESUMEN EJECUTIVO (SUMMARY BOX)</text>\n  <text x=\"450.0\" y=\"401.0\" fill=\"#334155\" font-size=\"11px\" font-weight=\"400\">Conclusion sintetica en 2 frases sobre la idea central de la clase.</text>\n  <rect x=\"1130.0\" y=\"70.0\" width=\"280.0\" height=\"370.0\" rx=\"6.0\" fill=\"#FFFFFF\" stroke=\"#CBD5E1\" stroke-width=\"1.5\" />\n  <text x=\"1150.0\" y=\"102.0\" fill=\"#0F172A\" font-size=\"12px\" font-weight=\"400\">ACCIONES POST-CLASE</text>\n  <text x=\"1150.0\" y=\"141.0\" fill=\"#475569\" font-size=\"11px\" font-weight=\"400\">[ ] Resolver guia taller #3\n[ ] Crear flashcards Anki\n[ ] Consultar capitulo 4 libro\n[ ] Repaso espaciado en 48h</text>\n</svg>"
